BEGIN; CREATE TEMP TABLE measured (LIKE user_totp_credentials INCLUDING ALL); INSERT INTO measured(tenant_id,user_id,secret_ciphertext,secret_key_id,confirmed_at,last_used_step) SELECT '00000000-0000-0000-0000-000000000001',md5('user-'||i)::uuid,decode(repeat('01',64),'hex'),'fixture-key','2026-10-01T00:00:00Z',123 FROM generate_series(1,10000) n(i); SELECT json_build_object('rows',count(*),'avg_tuple_bytes',avg(pg_column_size(d)),'heap_bytes',pg_table_size('measured'),'index_bytes',pg_indexes_size('measured'),'total_bytes',pg_total_relation_size('measured')) FROM measured d; ROLLBACK;